   365  int try_unserialize(struct usbredirparser *parser, FuzzedDataProvider *fdp)
   366  {
   367      std::vector<uint8_t> state;
   368      size_t len = fdp->ConsumeIntegralInRange<size_t>(1, 64 * 1024);
   369
   370      state.reserve(len);
   371
   372      if (len >= 4) {
   373          // Could also move USBREDIRPARSER_SERIALIZE_MAGIC after moving it to
   374          // a shared header.
   375          state.insert(state.end(), {'U', 'R', 'P', '1'});
   376          len -= 4;
   377      }
   378
   379      if (len > 0) {
   380          const std::vector<uint8_t> payload{fdp->ConsumeBytes<uint8_t>(len)};
   381
   382          state.insert(state.end(), payload.cbegin(), payload.cend());
   383      }
   384
   385      if (state.empty()) {
   386          return 0;
   387      }
   388
   389      state.shrink_to_fit();
   390
   391      return usbredirparser_unserialize(parser, &state[0], state.size());
   392  }
