   410  extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size)
   411  {
   412      std::array<uint32_t, USB_REDIR_CAPS_SIZE> caps = {0};
   413      int ret;
   414
   415      fdp = std::make_unique<FuzzedDataProvider>(data, size);
   416
   417      parser.reset(usbredirparser_create());
   418      if (parser == nullptr) {
   419          return 1;
