   433      parser->set_alt_setting_func = parser_set_alt_setting;
   434      parser->get_alt_setting_func = parser_get_alt_setting;
   435      parser->alt_setting_status_func = parser_alt_setting_status;
   436      parser->start_iso_stream_func = parser_start_iso_stream;
