   439      parser->start_interrupt_receiving_func = parser_start_interrupt_receiving;
   440      parser->stop_interrupt_receiving_func = parser_stop_interrupt_receiving;
   441      parser->interrupt_receiving_status_func = parser_interrupt_receiving_status;
   442      parser->alloc_bulk_streams_func = parser_alloc_bulk_streams;
   443      parser->free_bulk_streams_func = parser_free_bulk_streams;
   444      parser->bulk_streams_status_func = parser_bulk_streams_status;
   445      parser->cancel_data_packet_func = parser_cancel_data_packet;
   446      parser->control_packet_func = parser_control_packet;
   447      parser->bulk_packet_func = parser_bulk_packet;
   448      parser->iso_packet_func = parser_iso_packet;
   449      parser->interrupt_packet_func = parser_interrupt_packet;
   450      parser->alloc_lock_func = parser_alloc_lock;
   451      parser->lock_func = parser_lock;
   452      parser->unlock_func = parser_unlock;
   453      parser->free_lock_func = parser_free_lock;
   454      parser->hello_func = parser_hello;
   455      parser->filter_reject_func = parser_filter_reject;
   456      parser->filter_filter_func = parser_filter_filter;
   457      parser->device_disconnect_ack_func = parser_device_disconnect_ack;
   458      parser->start_bulk_receiving_func = parser_start_bulk_receiving;
   459      parser->stop_bulk_receiving_func = parser_stop_bulk_receiving;
   460      parser->bulk_receiving_status_func = parser_bulk_receiving_status;
   461      parser->buffered_bulk_packet_func = parser_buffered_bulk_packet;
   462
   463      for (uint32_t &cap : caps) {
   464          cap = fdp->ConsumeIntegral<decltype(caps)::value_type>();
   465      }
   466
   467      const int init_flags = fdp->ConsumeIntegral<uint8_t>() &
   468          (usbredirparser_fl_usb_host | usbredirparser_fl_no_hello);
   469
   470      usbredirparser_init(parser.get(), "fuzzer", caps.data(), caps.size(),
   471                          init_flags);
   472
   473      if (fdp->ConsumeBool() && try_unserialize(parser.get(), fdp.get()) != 0) {
   474          goto out;
   475      }
   476
   477      while (fdp->remaining_bytes() > 0 ||
   478             usbredirparser_has_data_to_write(parser.get())) {
   479          if (fdp->ConsumeBool() && try_serialize(parser.get()) != 0) {
   480              goto out;
   481          }
   482
   483          if (fdp->remaining_bytes() > 0) {
   484              ret = usbredirparser_do_read(parser.get());
   485
   486              switch (ret) {
   487              case usbredirparser_read_parse_error:
   488                  // Keep reading
   489                  break;
   490              default:
   491                  log("usbredirparser_do_read failed: %d\n", ret);
   492                  goto out;
   493              }
   494
   495              if (fdp->ConsumeBool() && try_serialize(parser.get()) != 0) {
   496                  goto out;
   497              }
   498          }
   499
   500          while (usbredirparser_has_data_to_write(parser.get())) {
   501              ret = usbredirparser_do_write(parser.get());
   502              if (ret < 0) {
   503                  log("usbredirparser_do_write failed: %d\n", ret);
   504                  goto out;
   505              }
   506          }
   507      }
   508
   509  out:
   510      parser.reset();
   511
   512      return 0;
   513  }
