  1497
  1498  #define USBREDIRPARSER_SERIALIZE_MAGIC        0x55525031
  1499  #define USBREDIRPARSER_SERIALIZE_BUF_SIZE     65536
  1500
  1501  /* Serialization format, send and receiving endian are expected to be the same!
  1502      uint32 MAGIC: 0x55525031 ascii: URP1 (UsbRedirParser version 1)
  1503      uint32 len: length of the entire serialized state, including MAGIC
  1504      uint32 our_caps_len
  1505      uint32 our_caps[our_caps_len]
  1506      uint32 peer_caps_len
  1507      uint32 peer_caps[peer_caps_len]
  1508      uint32 to_skip
  1509      uint32 header_read
  1510      uint8  header[header_read]
  1511      uint32 type_header_read
  1512      uint8  type_header[type_header_read]
  1513      uint32 data_read
  1514      uint8  data[data_read]
  1515      uint32 write_buf_count: followed by write_buf_count times:
  1516          uint32 write_buf_len
  1517          uint8  write_buf_data[write_buf_len]
  1518  */
  1519
  1520  static int serialize_alloc(struct usbredirparser_priv *parser,
  1521                             uint8_t **state, uint8_t **pos,
  1522                             uint32_t *remain, uint32_t needed)
  1523  {
  1524      uint8_t *old_state = *state;
  1525      uint32_t used, size;
  1526
  1527      if (*remain >= needed)
  1528          return 0;
  1529
  1530      used = *pos - *state;
  1531      size = (used + needed + USBREDIRPARSER_SERIALIZE_BUF_SIZE - 1) &
  1532             ~(USBREDIRPARSER_SERIALIZE_BUF_SIZE - 1);
  1533
  1534      *state = realloc(*state, size);
  1535      if (!*state) {
  1536          free(old_state);
  1537          ERROR("Out of memory allocating serialization buffer");
  1538          return -1;
  1539      }
  1540
  1541      *pos = *state + used;
  1542      *remain = size - used;
  1543
  1544      return 0;
  1545  }
