  1547  static int serialize_int(struct usbredirparser_priv *parser,
  1548                           uint8_t **state, uint8_t **pos, uint32_t *remain,
  1549                           uint32_t val, const char *desc)
  1550  {
  1551      DEBUG("serializing int %08x : %s", val, desc);
  1552
  1553      if (serialize_alloc(parser, state, pos, remain, sizeof(uint32_t)))
  1554          return -1;
  1555
  1556      memcpy(*pos, &val, sizeof(uint32_t));
  1557      *pos += sizeof(uint32_t);
  1558      *remain -= sizeof(uint32_t);
  1559
  1560      return 0;
  1561  }
  1562
  1563  static int unserialize_int(struct usbredirparser_priv *parser,
  1564                             uint8_t **pos, uint32_t *remain, uint32_t *val,
  1565                             const char *desc)
  1566  {
  1567      if (*remain < sizeof(uint32_t)) {
  1568          ERROR("error buffer underrun while unserializing state");
  1569          return -1;
  1570      }
  1571      memcpy(val, *pos, sizeof(uint32_t));
  1572      *pos += sizeof(uint32_t);
  1573      *remain -= sizeof(uint32_t);
  1574
  1575      DEBUG("unserialized int %08x : %s", *val, desc);
  1576
  1577      return 0;
  1578  }
  1579
  1580  static int serialize_data(struct usbredirparser_priv *parser,
  1581                            uint8_t **state, uint8_t **pos, uint32_t *remain,
  1582                            uint8_t *data, uint32_t len, const char *desc)
  1583  {
  1584      DEBUG("serializing %d bytes of %s data", len, desc);
  1585      if (len >= 8)
  1586          DEBUG("First 8 bytes of %s: %02x %02x %02x %02x %02x %02x %02x %02x",
  1587                desc, data[0], data[1], data[2], data[3],
  1588                      data[4], data[5], data[6], data[7]);
  1589
  1590      if (serialize_alloc(parser, state, pos, remain, sizeof(uint32_t) + len))
  1591          return -1;
  1592
  1593      memcpy(*pos, &len, sizeof(uint32_t));
  1594      *pos += sizeof(uint32_t);
  1595      *remain -= sizeof(uint32_t);
  1596
  1597      memcpy(*pos, data, len);
  1598      *pos += len;
  1599      *remain -= len;
  1600
  1601      return 0;
  1602  }
