  1604  /* If *data == NULL, allocs buffer dynamically, else len_in_out must contain
  1605     the length of the passed in buffer. */
  1606  static int unserialize_data(struct usbredirparser_priv *parser,
  1607                              uint8_t **pos, uint32_t *remain,
  1608                              uint8_t **data, uint32_t *len_in_out,
  1609                              const char *desc)
  1610  {
  1611      uint32_t len;
  1612
  1613      if (*remain < sizeof(uint32_t)) {
  1614          ERROR("error buffer underrun while unserializing state");
  1615          return -1;
  1616      }
  1617      memcpy(&len, *pos, sizeof(uint32_t));
  1618      *pos += sizeof(uint32_t);
  1619      *remain -= sizeof(uint32_t);
  1620
  1621      if (*remain < len) {
  1622          ERROR("error buffer underrun while unserializing state");
  1623          return -1;
  1624      }
  1625      if (*data == NULL && len > 0) {
  1626          *data = malloc(len);
  1627          if (!*data) {
  1628              ERROR("Out of memory allocating unserialize buffer");
  1629              return -1;
  1630          }
  1631      } else {
  1632          if (*len_in_out < len) {
  1633              ERROR("error buffer overrun while unserializing state");
  1634              return -1;
  1635          }
  1636      }
  1637
  1638      memcpy(*data, *pos, len);
  1639      *pos += len;
  1640      *remain -= len;
  1641      *len_in_out = len;
  1642
  1643      DEBUG("unserialized %d bytes of %s data", len, desc);
  1644      if (len >= 8)
  1645          DEBUG("First 8 bytes of %s: %02x %02x %02x %02x %02x %02x %02x %02x",
  1646                desc, (*data)[0], (*data)[1], (*data)[2], (*data)[3],
  1647                (*data)[4], (*data)[5], (*data)[6], (*data)[7]);
  1648
  1649      return 0;
  1650  }
