  1652  USBREDIR_VISIBLE
  1653  int usbredirparser_serialize(struct usbredirparser *parser_pub,
  1654                               uint8_t **state_dest, int *state_len)
  1655  {
  1656      struct usbredirparser_priv *parser =
  1657          (struct usbredirparser_priv *)parser_pub;
  1658      struct usbredirparser_buf *wbuf;
  1659      uint8_t *write_buf_count_pos, *state = NULL, *pos = NULL;
  1660      uint32_t write_buf_count = 0, len, remain = 0;
  1661
  1662      *state_dest = NULL;
  1663      *state_len = 0;
  1664
  1665      if (serialize_int(parser, &state, &pos, &remain,
  1666                                     USBREDIRPARSER_SERIALIZE_MAGIC, "magic"))
  1667          return -1;
  1668
  1669      /* To be replaced with length later */
  1670      if (serialize_int(parser, &state, &pos, &remain, 0, "length"))
  1671          return -1;
  1672
  1673      if (serialize_data(parser, &state, &pos, &remain,
  1674                         (uint8_t *)parser->our_caps,
  1675                         USB_REDIR_CAPS_SIZE * sizeof(int32_t), "our_caps"))
  1676          return -1;
  1677
  1678      if (parser->have_peer_caps) {
  1679          if (serialize_data(parser, &state, &pos, &remain,
  1680                             (uint8_t *)parser->peer_caps,
  1681                             USB_REDIR_CAPS_SIZE * sizeof(int32_t), "peer_caps"))
  1682              return -1;
  1683      } else {
  1684          if (serialize_int(parser, &state, &pos, &remain, 0, "peer_caps_len"))
  1685              return -1;
  1686      }
  1687
  1688      if (serialize_int(parser, &state, &pos, &remain, parser->to_skip, "skip"))
  1689          return -1;
  1690
  1691      if (serialize_data(parser, &state, &pos, &remain,
  1692                         (uint8_t *)&parser->header, parser->header_read,
  1693                         "header"))
  1694          return -1;
  1695
  1696      if (serialize_data(parser, &state, &pos, &remain,
  1697                         parser->type_header, parser->type_header_read,
  1698                         "type_header"))
  1699          return -1;
  1700
  1701      if (serialize_data(parser, &state, &pos, &remain,
  1702                         parser->data, parser->data_read, "packet-data"))
  1703          return -1;
  1704
  1705      write_buf_count_pos = pos;
  1706      /* To be replaced with write_buf_count later */
  1707      if (serialize_int(parser, &state, &pos, &remain, 0, "write_buf_count"))
  1708          return -1;
  1709
  1710      wbuf = parser->write_buf;
  1711      while (wbuf) {
  1712          if (serialize_data(parser, &state, &pos, &remain,
  1713                             wbuf->buf + wbuf->pos, wbuf->len - wbuf->pos,
  1714                             "write-buf"))
  1715              return -1;
  1716          write_buf_count++;
  1717          wbuf = wbuf->next;
  1718      }
  1719      /* Patch in write_buf_count */
  1720      memcpy(write_buf_count_pos, &write_buf_count, sizeof(int32_t));
  1721
  1722      /* Patch in length */
  1723      len = pos - state;
  1724      memcpy(state + sizeof(int32_t), &len, sizeof(int32_t));
  1725
  1726      *state_dest = state;
  1727      *state_len = len;
  1728
  1729      return 0;
  1730  }
